def old_naturalsize(value, binary=False, gnu=False, format="%.1f"):
    suffix = suffixes["gnu" if gnu else ("binary" if binary else "decimal")]
    base = 1024 if (gnu or binary) else 1000
    bytes_ = float(value)
    abs_bytes = abs(bytes_)
    if abs_bytes == 1 and not gnu:
        return _("%d Byte") % int(bytes_)
    if abs_bytes < base:
        return f"{int(bytes_)}B" if gnu else _("%d Bytes") % int(bytes_)
    exp = int(min(log := math.log(abs_bytes, base), len(suffix)))
    space = "" if gnu else " "
    return format % (bytes_ / (base ** exp)) + space + _(suffix[exp - 1])

