  // version) needs special casing: without it, the prerelease is
  // considered lower than the release on the same core version, so a
  // plain component-wise diff would miss the real bump level.
  if (lowHasPre && !highHasPre) {
    const sameCore =
      lowVersion.major === highVersion.major &&
      lowVersion.minor === highVersion.minor &&
      lowVersion.patch === highVersion.patch

    // If the low version has only a major (minor and patch both 0),
    // the release is always treated as a major -- reaching the first
    // stable X.0.0 line is a major-level event.
    if (!lowVersion.minor && !lowVersion.patch) {
      return 'major'
    }

    // The level is the first core component that differs.
    if (lowVersion.major !== highVersion.major) {
      return 'major'
