    // prerelease tag.  The level reflects what that release line means
    // semantically -- 1.1.0-pre -> 1.1.0 is a minor and
    // 1.0.1-pre -> 1.0.1 is a patch (the .0.0 case was handled above).
    if (!lowVersion.patch) {
      return 'minor'
    }

    return 'patch'
  }

