{"intent": "Classify differential results", "command": "cd work && cat > out/classify.js <<'EOF'
const path = require('path')
const A = require(path.resolve('orig/repo'))
const B = require(path.resolve('repo'))
const optsList = [{ includePrerelease: true }, {}, { includePrerelease: true, rtl: true }, { rtl: true }]
const cases = []
const preIds = ['7f3c','4821','a7f3','9x1d','0a','7','0','42','nightly','rc','5x','007a','7-3c','12ab','x1']
const mains = ['1','1.2','1.2.3','0.0.0','2.3.1','42.6.7']
const builds = [null,'','b','b.5','9b','9','build.9']
const preTails = ['', '-rc.5', '-7f3c', '-nightly.7f3c', '-nightly.4821.9e1d', '-4821', '-a7f3', '-0', '-1-2']
for (const m of mains) for (const p of preTails) for (const b of builds) cases.push(m + p + (b ? '+' + b : ''))
for (const id of preIds) cases.push('1.2.3-' + id, '1.2.3-nightly.' + id, '1.2.3-' + id + '+b.5', '1.2.3.' + id)
cases.push('version 1.2.3-nightly.7f3c', 'x2.3.1-nightly.7f3cy', '1.2.3-nightly.7f3c.9', 'v1.2.3-nightly.7f3c',
  '1.2.3.4-rc.5','1.2.3.4+rev.6','42.6.7.9.3-alpha','1.2.3.4','1.1-1','1.2.3-rc.5/a',' 1.2.3-7f3c ')
const kinds = {}
const unexpected = []
const rec = (k, ...info) => { kinds[k] = (kinds[k]||0)+1; if (k !== 'expected') unexpected.push([k, ...info]) }
for (const c of cases) {
  for (const o of optsList) {
    const a = A.coerce(c, o), b = B.coerce(c, o)
    const ka = a ? `${a.version}|${a.raw}` : 'null'
    const kb = b ? `${b.version}|${b.raw}` : 'null'
    if (ka === kb) continue
    const buildA = a ? (a.build||[]).join('.') : ''
    const buildB = b ? (b.build||[]).join('.') : ''
    if (buildA !== buildB) { rec('build-changed', JSON.stringify(c), JSON.stringify(o), ka, kb); continue }
    if (!a || !b) { rec('nullness', JSON.stringify(c), JSON.stringify(o), ka, kb); continue }
    const preA = (a.prerelease||[]).join('.'), preB = (b.prerelease||[]).join('.')
    const mainA = `${a.major}.${a.minor}.${a.patch}`, mainB = `${b.major}.${b.minor}.${b.patch}`
    if (mainA !== mainB) { rec('main-changed', JSON.stringify(c), JSON.stringify(o), ka, kb); continue }
    // prerelease changed: expected iff old prerelease is a truncation prefix of new one
    if (preB.startsWith(preA) && preA !== preB) {
      const tail = preB.slice(preA.length)
      rec(/^-?[0-9]/.test(tail.replace(/^[-.]/,'')) || true ? 'expected' : 'expected', JSON.stringify(c), JSON.stringify(o), ka, kb)
    } else {
      rec('pre-other', JSON.stringify(c), JSON.stringify(o), ka, kb)
    }
  }
}
console.log(kinds)
console.log('unexpected:', unexpected.length)
for (const u of unexpected.slice(0, 60)) console.log('  ', u.join('  '))
EOF
node out/classify.js > out/classify.txt 2>&1; head -70 out/classify.txt"}

