from boltons.setutils import IndexedSet
import random

def bounds(n):
    vals = {None, 0, 1, -1, n - 1, -n, n, -n - 2, n + 2, n // 2, -(n // 2), -3, 3}
    return sorted((v for v in vals if v is None or -n - 3 <= v <= n + 3),
                  key=lambda v: (v is None, v if v is not None else 0))

def probe(items, removes, label):
    s = IndexedSet(items)
    for r in removes: s.remove(r)
    fresh = IndexedSet([i for i in items if i not in set(removes)])
    lst = list(fresh)
    probs = []
