import math, random, re
from math import log
from humanize.filesize import suffixes, naturalsize

def old_naturalsize(value, binary=False, gnu=False, format="%.1f"):
    if gnu: suffix = suffixes["gnu"]
    elif binary: suffix = suffixes["binary"]
    else: suffix = suffixes["decimal"]
    base = 1024 if (gnu or binary) else 1000
    bytes_ = float(value); abs_bytes = abs(bytes_)
    if abs_bytes == 1 and not gnu: return "%d Byte" % int(bytes_)
    if abs_bytes < base: return f"{int(bytes_)}B" if gnu else "%d Bytes" % int(bytes_)
    exp = int(min(log(abs_bytes, base), len(suffix)))
    space = "" if gnu else " "
    return format % (bytes_ / (base**exp)) + space + suffix[exp - 1]

def expected(value, binary=False, gnu=False, format="%.1f"):
    """Spec from the bug report: minimal unit index whose formatted display < base,
    capped at the largest unit."""
    suffix = suffixes["gnu"] if gnu else (suffixes["binary"] if binary else suffixes["decimal"])
    base = 1024 if (gnu or binary) else 1000
    bytes_ = float(value); abs_bytes = abs(bytes_)
    if abs_bytes == 1 and not gnu: return "%d Byte" % int(bytes_)
    if abs_bytes < base: return f"{int(bytes_)}B" if gnu else "%d Bytes" % int(bytes_)
    exp = int(min(log(abs_bytes, base), len(suffix)))
    space = "" if gnu else " "
    while exp < len(suffix):
        try:
            disp = abs(float(format % (bytes_/base**exp)))
        except Exception:
            break  # spec undefined for unparseable formats
        if disp < base: break
        exp += 1
    return format % (bytes_/base**exp) + space + suffix[exp - 1]

def sweep():
    random.seed(0)
    diffs = []
    specs = []
    for binary in (False, True):
        for gnu in (False, True):
            base = 1024 if (gnu or binary) else 1000
            n = len(suffixes["gnu"])
            values = set()
            for k in range(1, n+2):
                b = base**k
                for d in list(range(-40, 41)) + [int(b*f) for f in (0.99999,0.999995,0.999996,0.9999995,0.99999996,1.0000001,1.000001)]:
                    v = b + d if d <= 0 else d
                    if v >= base: values.add(v)
                # rounding-boundary values: b * (1 - eps) so mantissa rounds up to base
                for m in range(1, 60):
                    v = int(b * (1 - m*1e-5))
                    if v >= base: values.add(v)
            for _ in range(3000):
                v = int(base ** random.uniform(1.0, n+2))
                if v >= base: values.add(v)
            for fmt in ("%.1f", "%.2f", "%.3f", "%.0f", "%d", "%s", "%+.1f", "%.1e"):
                for v in values:
                    try: o = old_naturalsize(v, binary, gnu, fmt)
                    except Exception as e: o = f"ERR:{type(e).__name__}"
                    try: w = naturalsize(v, binary, gnu, fmt)
                    except Exception as e: w = f"ERR:{type(e).__name__}"
                    try: e = expected(v, binary, gnu, fmt)
                    except Exception as e2: e = f"ERR:{type(e2).__name__}"
                    if o != w: diffs.append((v, binary, gnu, fmt, o, w))
                    if w != e: specs.append((v, binary, gnu, fmt, o, w, e))
    return diffs, specs

diffs, specs = sweep()
print("total old!=new:", len(diffs), " new!=spec:", len(specs))
print("--- new != spec (first 40) ---")
for s in specs[:40]: print(s)
