import math, random, re
import humanize

def sig_digits(s):
    # strip sign, unit/prefix/space; count significant digits of the number part
    m = re.match(r'^(-?)(\d+)(?:\.(\d+))?([a-zA-ZμΩ°].*)?$', s)
    if not m:
        return None  # scientific or other
    intpart, frac, rest = m.group(2), m.group(3) or '', m.group(4) or ''
    # significant digits: int part (no leading zeros here) + frac, but trailing
    # zeros in int part are significant due to rounding; frac always significant
    # after decimal point present. If no frac, all int digits significant.
    return len(intpart.lstrip('0') or '0') + (len(frac) if frac else 0) if intpart != '0' else len(frac.lstrip('0'))

bad = []
random.seed(1)
vals = []
for e in range(-32, 34):
    for _ in range(30):
        vals.append(10**e * random.uniform(0.5, 2))
        vals.append(10**e * random.uniform(0.99, 1.001))
        vals.append(10**e * random.uniform(0.099, 10))
for p in range(1, 7):
    for v in vals:
        if v == 0 or not math.isfinite(v):
            continue
        out = humanize.metric(v, "X", p)
        if 'x 10' in out:
            continue
        e = math.floor(math.log10(abs(v)))
        k = e % 3 + 1
        if p <= k:
            continue  # digits clamped to 0; existing behavior tolerated
        sd = sig_digits(out)
        if sd != p:
            bad.append((v, p, out, sd, k))
print("violations:", len(bad))
for b in bad[:20]:
    print(b)
