import math, random, re
import humanize

def old_metric(value, unit="", precision=3):
    if not math.isfinite(value):
        return humanize.number._format_not_finite(value)
    exponent = math.floor(math.log10(abs(value))) if value != 0 else 0
    if exponent >= 33 or exponent < -30:
        return humanize.scientific(value, precision - 1) + unit
    old_bucket = exponent // 3 * 3
    value /= 10**old_bucket
    digits = int(max(0, precision - exponent % 3 - 1))
    if exponent < 30 and round(abs(value), digits) >= 1000:
        exponent += 3 - exponent % 3
        new_bucket = exponent // 3 * 3
        value /= 10 ** (new_bucket - old_bucket)
        digits = int(max(0, precision - exponent % 3 - 1))
    if exponent >= 3:
        ordinal_ = "kMGTPEZYRQ"[exponent // 3 - 1]
    elif exponent < 0:
        ordinal_ = "mμnpfazyrq"[(-exponent - 1) // 3]
    else:
        ordinal_ = ""
    value_ = format(value, f".{digits}f")
    space = "" if not (unit or ordinal_) or unit in ("°", "′", "″") else " "
    return f"{value_}{space}{ordinal_}{unit}"

def sig(s):
    num = s.split(' ')[0]
    if 'x' in num and 'e' in num.lower() and 'x' in num:
        pass
    if re.search(r'x ?10', s):
        # scientific: count mantissa digits: d.ddd x 10^n
        m = re.match(r'^(-?\d+)(?:\.(\d+))? x 10', s)
        if m:
            return int(m.group(1)) // 10 ** len(m.group(2) or '') and None or None
        return ('SCI', s)
    m = re.match(r'^(-?)(\d+)(?:\.(\d+))?$', num)
    if not m: return ('UNP', s)
    i, f = m.group(2), m.group(3) or ''
    if i == '0': return len(f.lstrip('0'))
    return len(i.lstrip('0')) + (len(f) if f else 0)

def sci_sig(s):
    m = re.match(r'^(-?)(\d+)(?:\.(\d+))? x 10', s)
    if not m: return None
    i, f = m.group(2), m.group(3) or ''
    return len(i) + (len(f) if f else 0)

random.seed(2)
vals = [0.0, 1.0, -1.0, 999.8, 999.99, 1e-14, 1e25, 1e26, 0.12, 10.5123, 1.5123,
        9.9996e32, 999.96e30, -9.9996e32, 1e33, 1e30, 9.996e30, 99.96e30, 999.6e30]
for e in range(-33, 35):
    for _ in range(40):
        vals.append(10**e * random.uniform(0.09, 10))
        vals.append(10**e * random.uniform(0.999, 1.001))
        vals.append(-10**e * random.uniform(0.99, 1.01))
same = fixed = other = 0
others = []
for p in range(0, 7):
    for v in vals:
        try:
            o = old_metric(v, "X", p)
            oe = None
        except Exception as exc:
            o, oe = f"ERR", type(exc).__name__
        try:
            n = humanize.metric(v, "X", p)
            ne = None
        except Exception as exc:
            n, ne = "ERR", type(exc).__name__
        if (o, oe) == (n, ne):
            same += 1
            continue
        e = math.floor(math.log10(abs(v))) if v != 0 else 0
        k = e % 3 + 1
        # classify: is the new output within precision?
        if re.search(r'x 10', n):
            ns = sci_sig(n)
        else:
            ns = sig(n)
        os_ = sig(o) if not o.startswith('ERR') else None
        if p <= k:
            # digits clamped: old behavior should be preserved except exp-32 scientific
            others.append((v, p, o, n, os_, ns, k))
        elif os_ is not None and isinstance(os_, int) and os_ > p and ns == p:
            fixed += 1
        else:
            others.append((v, p, o, n, os_, ns, k))
print("same:", same, "| fixed:", fixed, "| other-diffs:", len(others))
for x in others[:40]: print(x)
